import { defineConfig } from 'vite'
import honox from 'honox/vite'

export default defineConfig({
  plugins: [honox()],
  esbuild: {
    jsx: 'automatic',
    jsxImportSource: 'hono/jsx',
  },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    ssr: 'app/server.ts',
    rollupOptions: {
      output: {
        entryFileNames: 'server.js',
        chunkFileNames: 'assets/[name].js',
        assetFileNames: 'assets/[name].[ext]',
      },
    },
  },
})

import { Hono } from 'hono'
import { createApp } from 'honox/server'

export type RsvpEntry = {
  name: string
  email: string
  attendance: string
}

const inner = createApp()

export function createHonoxRsvpApp(responses: RsvpEntry[]) {
  const app = new Hono()
  app.use('*', async (c, next) => {
    ;(c as any).set('rsvpResponses', responses)
    await next()
  })
  app.notFound((c) => c.text('Not Found', 404))
  app.route('/', inner)
  return app
}

export default createHonoxRsvpApp([])

import { jsxRenderer } from 'hono/jsx-renderer'

export default jsxRenderer(({ children }) => {
  return (
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>RSVP</title>
      </head>
      <body>{children}</body>
    </html>
  )
})

import { createRoute } from 'honox/factory'

type RsvpEntry = {
  name: string
  email: string
  attendance: string
}

function getStore(c: any): RsvpEntry[] {
  const value = c.get('rsvpResponses')
  if (Array.isArray(value)) {
    return value as RsvpEntry[]
  }
  return []
}

function isValidEmail(value: string): boolean {
  if (/\s/.test(value)) {
    return false
  }
  const first = value.indexOf('@')
  const last = value.lastIndexOf('@')
  if (first <= 0 || first !== last || first === value.length - 1) {
    return false
  }
  const local = value.slice(0, first)
  const domain = value.slice(first + 1)
  if (!local || !domain) {
    return false
  }
  return true
}

export default createRoute((c: any) => {
  const responses = getStore(c)
  return c.render(
    <>
      <h1>RSVP</h1>
      <form id="rsvp-response" method="post">
        <label>
          Name
          <input type="text" name="name" required />
        </label>
        <label>
          Email
          <input type="email" name="email" required />
        </label>
        <fieldset>
          <legend>Attendance</legend>
          <label>
            <input type="radio" name="attendance" value="yes" required />
            Yes
          </label>
          <label>
            <input type="radio" name="attendance" value="no" required />
            No
          </label>
          <label>
            <input type="radio" name="attendance" value="maybe" required />
            Maybe
          </label>
        </fieldset>
        <button type="submit">Submit</button>
      </form>
      <section>
        <h2>Responses</h2>
        <ul>
          {responses.map((entry, index) => (
            <li key={index}>
              <span>{entry.name}</span> <span>{entry.email}</span>{' '}
              <span>{entry.attendance}</span>
            </li>
          ))}
        </ul>
      </section>
    </>,
  )
})

export const POST = createRoute(async (c: any) => {
  const rawType = c.req.header('content-type') ?? ''
  const mime = rawType.split(';')[0].trim().toLowerCase()
  if (mime !== 'application/x-www-form-urlencoded') {
    return c.text('Unsupported Media Type', 415)
  }
  const bodyText = await c.req.text()
  const params = new URLSearchParams(bodyText)
  const names = params.getAll('name')
  const emails = params.getAll('email')
  const attendances = params.getAll('attendance')
  if (names.length !== 1 || emails.length !== 1 || attendances.length !== 1) {
    return c.text('Invalid submission', 400)
  }
  const name = names[0].trim()
  const email = emails[0].trim()
  const attendance = attendances[0].trim()
  if (!name || !email || !attendance) {
    return c.text('Invalid submission', 400)
  }
  if (attendance !== 'yes' && attendance !== 'no' && attendance !== 'maybe') {
    return c.text('Invalid submission', 400)
  }
  if (!isValidEmail(email)) {
    return c.text('Invalid submission', 400)
  }
  const store = getStore(c)
  store.push({ name, email, attendance })
  return c.redirect('/rsvp', 303)
})

export const PUT = createRoute((c: any) => {
  return c.text('Method Not Allowed', 405)
})

export const DELETE = createRoute((c: any) => {
  return c.text('Method Not Allowed', 405)
})

export const PATCH = createRoute((c: any) => {
  return c.text('Method Not Allowed', 405)
})

import { createHonoxRsvpApp } from '../dist/server.js'

export async function createRsvpApp() {
  const responses = []
  const app = createHonoxRsvpApp(responses)
  return {
    fetch: (request, ...rest) => app.fetch(request, ...rest),
  }
}
